SELECT pk_id, id, tenant_id, target_people_id, operator_type, operator_id, biz_type, biz_key,
       version_before, version_after, org_id,
       is_deleted, gmt_created, gmt_modified, gmt_deleted
FROM field_revision_batch
WHERE tenant_id = #{tenantId}
  AND target_people_id = #{targetPeopleId}
  AND biz_type = #{bizType}
  AND is_deleted = 0

      AND biz_key = #{bizKey}

ORDER BY gmt_created DESC
LIMIT 100
